assert req['model']=='gemini-3.8-flash-tts' and len(req['units'])==40 and req['automaticRetries']==0
files=['worker.py','request.json','runtime.json','source-coverage.json','remote-branch-probe.json','preserved-inputs.json','worker-derivation.json','implementation-dependency-pins.json','README.en.md','offline_tests.py','freeze_package.py','.gitignore','vendor/pipeline-engine.py','vendor/course/manifest.json']
