lines=['name: S1-11 first-created-branch connected narration r3','on:','  push:','    branches:','      - work/soil-s111-narration-20261022-r3','permissions:','  contents: read','concurrency:','  group: s111-connected-r3-'+rq,'  cancel-in-progress: false','env:','  PACKAGE: '+PACKAGE,'  REQUEST_SHA: '+rq,'  WORKER_SHA: '+wr,'  FREEZE_SHA: '+fr,"  PYTHONUNBUFFERED: '1'","  HF_HUB_DISABLE_TELEMETRY: '1'","  OMP_NUM_THREADS: '2'",'jobs:','  narration:',"    if: github.repository == 'cabicci/viva-ai-systems-55d35820' && github.ref == 'refs/heads/work/soil-s111-narration-20261022-r3' && github.event_name == 'push' && github.event.created == true && github.event.deleted == false && github.run_attempt == 1",'    runs-on: ubuntu-22.04','    timeout-minutes: 360','    steps:','      - uses: actions/checkout@11d5960a326750d5838078e36cf38b85af677262','      - uses: actions/setup-python@a26af69be951a213d495a4c3e4e4022e16d87065','        with:',"          python-version: '3.11'",'      - name: Validate frozen complete teaching projection and exact fresh-push scope','        run: |','          cd "$PACKAGE"','          python worker.py validate','      - name: Exact preferred-model metadata preflight; no fallback','        env:','          GEMINI_API_KEY: ${{ secrets.GEMINI_API_KEY }}','        run: |','          cd "$PACKAGE"','          python worker.py preflight','      - name: Install hash-verified Whisper runtime once','        run: |','          cd "$PACKAGE"','          python -m pip download --no-deps --dest wheels faster-whisper==1.2.1','          python worker.py verify-wheel','          python -m pip install --disable-pip-version-check --report output/pip-install-report.json wheels/faster_whisper-1.2.1-*.whl']
